/* Anime Girl RNG Wiki — localize next update times.
 * Reads standard <time datetime="..."> elements generated by Template:MainPageUpdates.
 */
(function () {
    'use strict';

    function formatLocalTime(root) {
        root = root || document;

        var nodes = root.querySelectorAll
            ? root.querySelectorAll('time.agrng-local-update-time[datetime]')
            : [];

        Array.prototype.forEach.call(nodes, function (node) {
            var raw = node.getAttribute('datetime');
            var date = new Date(raw);

            if (!raw || isNaN(date.getTime())) {
                return;
            }

            var dateText = new Intl.DateTimeFormat('en-US', {
                month: 'long',
                day: 'numeric',
                year: 'numeric'
            }).format(date);

            var timeText = new Intl.DateTimeFormat('en-US', {
                hour: 'numeric',
                minute: '2-digit',
                timeZoneName: 'short'
            }).format(date);

            node.textContent = dateText + ' · ' + timeText;
            node.title = 'Shown in your local time zone';
        });
    }

    function init() {
        formatLocalTime(document);
    }

    if (window.mw && mw.hook) {
        mw.hook('wikipage.content').add(function ($content) {
            var root = $content && $content[0] ? $content[0] : document;
            formatLocalTime(root);
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
}());


/* =========================================================
 * RELICS — TRUE TIER-BOUNDARY HOVER FLIP
 *
 * The tooltip normally opens to the RIGHT.
 * When a Relic is hovered, measure that card against ITS OWN
 * .agrng-relic-tier-box. Flip LEFT only when the full tooltip
 * would not fit on the right and the left side has more room.
 * ========================================================= */
(function () {
    'use strict';

    var CARD = '.page-Relics .agrng-relic-browser-card';
    var HOVER = '.agrng-relic-browser-hover';
    var TIER = '.agrng-relic-tier-box';
    var LEFT_CLASS = 'agrng-relic-hover-open-left';
    var GAP = 9;

    function chooseRelicHoverSide(card) {
        if (!card) {
            return;
        }

        var hover = card.querySelector(HOVER);
        var tier = card.closest(TIER);

        if (!hover || !tier) {
            card.classList.remove(LEFT_CLASS);
            return;
        }

        /* Remove the old decision before measuring so every hover is fresh. */
        card.classList.remove(LEFT_CLASS);

        var cardRect = card.getBoundingClientRect();
        var tierRect = tier.getBoundingClientRect();

        /*
         * offsetWidth works even while visibility:hidden, unlike dimensions
         * based on painted pixels. Fall back to the CSS width if necessary.
         */
        var hoverWidth = hover.offsetWidth || 310;
        var needed = hoverWidth + GAP;

        var roomRight = tierRect.right - cardRect.right;
        var roomLeft = cardRect.left - tierRect.left;

        /*
         * Right is always preferred.
         * Flip only when the complete tooltip cannot fit on the right.
         * If neither side fully fits, use whichever side has more room.
         */
        var openLeft =
            roomRight < needed &&
            (roomLeft >= needed || roomLeft > roomRight);

        card.classList.toggle(LEFT_CLASS, openLeft);
    }

    /* mouseover bubbles, so this also works for dynamically produced DPL cards. */
    document.addEventListener('mouseover', function (event) {
        var card = event.target.closest && event.target.closest(CARD);

        if (!card) {
            return;
        }

        /* Ignore movement between children of the same card. */
        if (event.relatedTarget && card.contains(event.relatedTarget)) {
            return;
        }

        chooseRelicHoverSide(card);
    });

    /* Keyboard navigation gets the same behavior. */
    document.addEventListener('focusin', function (event) {
        var card = event.target.closest && event.target.closest(CARD);

        if (card) {
            chooseRelicHoverSide(card);
        }
    });

    /* Recalculate on the next hover after any viewport resize. */
    window.addEventListener('resize', function () {
        var cards = document.querySelectorAll(CARD);
        for (var i = 0; i < cards.length; i++) {
            cards[i].classList.remove(LEFT_CLASS);
        }
    });
}());